final_template:
AWSTemplateFormatVersion: "2010-09-09"

Description: >
  Creates an Amazon Verified Permissions policy store implementing
  Cedar-based access control for the bookstore application. The policy store
  embeds a strict Cedar JSON schema (Bookstore namespace modeling Role, User,
  and Book entities with View and ViewWithPremiumOffers actions) and applies
  a set of static Cedar policies. The policy store ID is published to SSM
  Parameter Store so other parts of the stack can reference it.

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Cedar authorization policy store for the bookstore application
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  },
                  "memberOfTypes": [
                    "Role"
                  ]
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "Bookstore::User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }
      ValidationSettings:
        Mode: STRICT
      Tags:
        - Key: Application
          Value: Bookstore
        - Key: Component
          Value: Authorization

  AdminViewAllBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Users in the Admin role may view any book
          Statement: |-
            permit(principal in Bookstore::Role::"Admin", action == Bookstore::Action::"View", resource);

  ForbidNamedAdminViewBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid the named administrator alice from viewing books, overriding the general Admin role permission
          Statement: |-
            forbid(principal == Bookstore::User::"alice", action == Bookstore::Action::"View", resource);

  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Users in the Publisher role may view only the books they own
          Statement: |-
            permit(principal in Bookstore::Role::"Publisher", action == Bookstore::Action::"View", resource) when { resource.owner == principal };

  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Named user charlie may view the named book book-123
          Statement: |-
            permit(principal == Bookstore::User::"charlie", action == Bookstore::Action::"View", resource == Bookstore::Book::"book-123");

  CustomerViewPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Users in the Customer role may view premium offers once they have been a member for two years or more
          Statement: |-
            permit(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource) when { principal has yearsAsMember && principal.yearsAsMember >= 2 };

  ForbidShortTenureCustomersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid customers with less than two years of membership from viewing premium offers
          Statement: |-
            forbid(principal in Bookstore::Role::"Customer", action == Bookstore::Action::"ViewWithPremiumOffers", resource) when { principal has yearsAsMember && principal.yearsAsMember < 2 };

  RegionRestrictionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the View and ViewWithPremiumOffers actions entirely whenever the request context region is not the United States
          Statement: |-
            forbid(principal, action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"], resource) when { context.region != "US" };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Sub "/bookstore/${AWS::StackName}/verified-permissions/policy-store-id"
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Amazon Verified Permissions policy store ID for the bookstore application

Outputs:

  PolicyStoreId:
    Description: ID of the Amazon Verified Permissions policy store
    Value: !Ref BookstorePolicyStore

  PolicyStoreArn:
    Description: ARN of the Amazon Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.Arn

  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter containing the policy store ID
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: >
  Self-contained AWS AppSync GraphQL API (TodoAPIwithJs) with API key
  authentication, backed by a DynamoDB table with a global secondary index on
  the owner attribute. Full CRUD, a query-by-owner operation and real-time
  subscriptions are implemented using JavaScript resolvers deployed as
  pipeline resolvers with one JavaScript function per data operation.

Resources:

  # ================================================================
  # DynamoDB table: partition key "id". Global secondary index
  # "ownerIndex" partitions on "owner" and sorts on "createdAt" so
  # Todo items can be queried by owner.
  # ================================================================
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub '${AWS::StackName}-Todos'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
        - AttributeName: createdAt
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: ownerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: createdAt
              KeyType: RANGE
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      Tags:
        - Key: Name
          Value: TodoTable

  # ================================================================
  # IAM role assumed by AppSync to access the Todo table
  # ================================================================
  AppSyncDynamoDbRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:DeleteItem
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:Query
                  - dynamodb:Scan
                  - dynamodb:UpdateItem
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  # ================================================================
  # GraphQL API with API key authentication
  # ================================================================
  TodoGraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Description: Default API key for TodoAPIwithJs

  # ================================================================
  # GraphQL schema
  # ================================================================
  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String
          title: String!
          content: String
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }

        input CreateTodoInput {
          owner: String
          title: String!
          content: String
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          content: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  # ================================================================
  # DynamoDB data source
  # ================================================================
  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDbRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  # ================================================================
  # JavaScript functions: one function per data operation
  # ================================================================
  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: CreateTodoFunction
      Description: JavaScript function that puts a new Todo item into DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = util.autoId();
          const now = util.time.nowISO8601();

          const item = {
            id: id,
            title: input.title,
            createdAt: now,
            updatedAt: now,
          };

          if (input.owner !== undefined && input.owner !== null) {
            item.owner = input.owner;
          }
          if (input.content !== undefined && input.content !== null) {
            item.content = input.content;
          }

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: UpdateTodoFunction
      Description: JavaScript function that updates an existing Todo item in DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;

          const values = {
            updatedAt: util.time.nowISO8601(),
          };

          if (input.owner !== undefined && input.owner !== null) {
            values.owner = input.owner;
          }
          if (input.title !== undefined && input.title !== null) {
            values.title = input.title;
          }
          if (input.content !== undefined && input.content !== null) {
            values.content = input.content;
          }

          const names = {};
          const vals = {};
          const sets = [];

          Object.keys(values).forEach(function (field) {
            names['#' + field] = field;
            vals[':' + field] = values[field];
            sets.push('#' + field + ' = :' + field);
          });

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(vals),
            },
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: {
                '#id': 'id',
              },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: DeleteTodoFunction
      Description: JavaScript function that deletes a Todo item from DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: {
                '#id': 'id',
              },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: GetTodoFunction
      Description: JavaScript function that fetches a single Todo item from DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: ListTodosFunction
      Description: JavaScript function that scans all Todo items from DynamoDB
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const req = {
            operation: 'Scan',
            limit: 20,
          };

          if (ctx.args.limit !== undefined && ctx.args.limit !== null) {
            req.limit = ctx.args.limit;
          }
          if (ctx.args.nextToken !== undefined && ctx.args.nextToken !== null) {
            req.nextToken = ctx.args.nextToken;
          }

          return req;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  TodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      Name: TodosByOwnerFunction
      Description: JavaScript function that queries the ownerIndex GSI by owner
      DataSourceName: !GetAtt TodoTableDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const req = {
            operation: 'Query',
            index: 'ownerIndex',
            limit: 20,
            scanIndexForward: false,
            query: {
              expression: '#owner = :owner',
              expressionNames: {
                '#owner': 'owner',
              },
              expressionValues: util.dynamodb.toMapValues({
                ':owner': ctx.args.owner,
              }),
            },
          };

          if (ctx.args.limit !== undefined && ctx.args.limit !== null) {
            req.limit = ctx.args.limit;
          }
          if (ctx.args.nextToken !== undefined && ctx.args.nextToken !== null) {
            req.nextToken = ctx.args.nextToken;
          }

          return req;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  # ================================================================
  # Pipeline resolvers: one resolver per GraphQL field, each with a
  # single JavaScript function from the pipeline. Resolver-level code
  # exports only the APPSYNC_JS pipeline handlers `request` (pre
  # stage) and `response` (post stage); the data work is done by the
  # pipeline functions referenced in PipelineConfig by FunctionId.
  # ================================================================
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          // Pre-stage: runs before the first pipeline function.
          return {};
        }

        export function response(ctx) {
          // Post-stage: the result of the last pipeline function.
          return ctx.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt TodosByOwnerFunction.FunctionId

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID for TodoAPIwithJs
    Value: !GetAtt TodoGraphQLApi.ApiId
  GraphQLEndpoint:
    Description: AppSync GraphQL endpoint URL
    Value: !GetAtt TodoGraphQLApi.GraphQLUrl
  ApiKeyValue:
    Description: API key used to authenticate GraphQL requests
    Value: !GetAtt GraphQLApiKey.ApiKey
  TodoTableName:
    Description: Name of the DynamoDB table storing Todo items
    Value: !Ref TodoTable

AWSTemplateFormatVersion: '2010-09-09'
Description: SimpleTodoAPI GraphQL API on AWS AppSync backed by DynamoDB with JavaScript resolvers and API key authentication.

Resources:
  SimpleTodoGraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncLoggingRole.Arn
        FieldLogLevel: ERROR

  AppSyncLoggingRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncCloudWatchLogs
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:*'

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      Description: API key for SimpleTodoAPI testing

  SimpleTodoGraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
        }

        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          status: String
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }

        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          status: String
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          description: String
          status: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]!
          todosByOwner(owner: String!): [Todo]!
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo!
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: ownerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  TodoTableAccessRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableReadWrite
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      Name: TodoTable
      Description: DynamoDB data source backing the to-do resolvers
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt TodoTableAccessRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodoTable

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues({
              owner: input.owner,
              title: input.title,
              description: input.description ? input.description : '',
              status: input.status ? input.status : 'PENDING',
              createdAt: now,
              updatedAt: now,
            }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id } = ctx.args.input;
          const { owner } = ctx.args.input;
          const { title } = ctx.args.input;
          const { description } = ctx.args.input;
          const { status } = ctx.args.input;
          const expNames = {};
          const expValues = {};
          const expSet = [];
          if (owner !== undefined && owner !== null) {
            expNames['#owner'] = 'owner';
            expValues[':owner'] = owner;
            expSet.push('#owner = :owner');
          }
          if (title !== undefined && title !== null) {
            expNames['#title'] = 'title';
            expValues[':title'] = title;
            expSet.push('#title = :title');
          }
          if (description !== undefined && description !== null) {
            expNames['#description'] = 'description';
            expValues[':description'] = description;
            expSet.push('#description = :description');
          }
          if (status !== undefined && status !== null) {
            expNames['#status'] = 'status';
            expValues[':status'] = status;
            expSet.push('#status = :status');
          }
          expNames['#updatedAt'] = 'updatedAt';
          expValues[':updatedAt'] = util.time.nowISO8601();
          expSet.push('#updatedAt = :updatedAt');
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + expSet.join(', '),
              expressionNames: expNames,
              expressionValues: util.dynamodb.toMapValues(expValues),
            },
            condition: {
              expression: 'attribute_exists(id)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
            condition: {
              expression: 'attribute_exists(id)',
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - SimpleTodoGraphQLSchema
      - TodoTableDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoGraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner } = ctx.args;
          return {
            operation: 'Query',
            index: 'ownerIndex',
            query: {
              expression: 'owner = :owner',
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
          };
        }

        export function response(ctx) {
          return ctx.result.items;
        }

Outputs:
  GraphQLApiEndpoint:
    Description: Endpoint URL of the SimpleTodoAPI GraphQL API
    Value: !GetAtt SimpleTodoGraphQLApi.GraphQLUrl
  GraphQLApiId:
    Description: AppSync API identifier
    Value: !GetAtt SimpleTodoGraphQLApi.ApiId
  GraphQLApiKey:
    Description: API key for authenticating requests to SimpleTodoAPI
    Value: !GetAtt SimpleTodoApiKey.ApiKey
  TodosTableName:
    Description: Name of the DynamoDB table backing the API
    Value: !Ref TodoTable
